// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReceiverAlwaysSucceeds receiver;

    function setUp() public { 
        c = new C();
        receiver = new ReceiverAlwaysSucceeds();
    }

    // fuzzed params: an address 'from' and an array of addresses 'tos' and values
    function testFuzz_property(address from, address[] memory tos, uint256 v, uint8 decimals) public {
        // admissible domain: tos must be non-empty (the function requires this)
        vm.assume(tos.length > 0);
        // keep decimals in a reasonable range to avoid overflow in multiplication
        decimals = uint8(decimals % 18);
        // Bind v to a wide but safe range to avoid overflow when computing v * 10 ** decimals
        v = bound(v, 0, type(uint256).max / 10 ** decimals);

        // call through the receiver contract address which implements the expected transferFrom signature
        bool ok;
        try c.transfer(from, address(receiver), tos, v, decimals) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: for any admissible input (tos non-empty and callee accepts calls), reference returns true (call does not revert)
        // We observe C only via its external return (captured by try/catch as ok). The buggy mutant that returns false but does not revert
        // will still make the call succeed (ok == true). However our property must distinguish return value true vs false; since try/catch only tells us about revert, we need to observe the return boolean directly.
        // Instead call and capture the returned bool via low-level call to read the returned boolean value.
        // Do that now to produce the single assertion reading c's public behavior.
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256,uint256)", from, address(receiver), tos, v, uint256(decimals)));
        // success indicates the call did not revert; data should contain the returned bool when success==true
        // decode returned bool if present
        bool returnedBool = false;
        if (success && data.length >= 32) {
            returnedBool = abi.decode(data, (bool));
        }

        // The single assertion: the reference implementation always returns true for these admissible inputs (non-empty tos and a callee that succeeds);
        // the mutant that changed `return true;` to `return false;` will cause returnedBool==false for some inputs and thus fail this assertion.
        assertTrue(returnedBool);
    }
}

// Minimal adversarial helper that always succeeds on calls to transferFrom(address,address,uint256)
contract ReceiverAlwaysSucceeds {
    // implement a generic fallback that accepts any call and returns true (encoded bool) when selector matches transferFrom
    fallback() external payable returns (bytes memory) {
        // if called with any data, just return abi.encode(true) so the caller sees success and a true return value from the callee function
        return abi.encode(true);
    }

    receive() external payable {}
}

