pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: from address, number of tos, value and decimals
    function testFuzz_property(address from, uint8 tosCount, uint256 v, uint8 _decimals) public {
        // keep tosCount in a reasonable non-zero range to satisfy require(_tos.length > 0)
        uint256 n = bound(tosCount, 1, 8);
        // build tos array of helper contracts that accept the call
        address[] memory tos = new address[](n);
        // deploy a fresh AcceptingCallee for each entry so calls succeed
        for (uint i = 0; i < n; i++) {
            AcceptingCallee a = new AcceptingCallee();
            tos[i] = address(a);
        }

        // The property: for any admissible inputs (non-empty tos), a successful return from c.transfer(...) is true.
        // We cannot call c.transfer from an EOA that supplies code — c.transfer is public and does low-level call to tos entries.
        // Call and capture whether the call completed (did not revert) and the boolean return value.

        bool ok;
        bool ret;
        // call and capture revert vs success and returned bool
        try c.transfer(from, address(this), tos, v, _decimals) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // The single assertion: if the call completed (ok==true), then it must have returned true.
        // This holds for the reference contract for all inputs; the mutant that returns false breaks this for some inputs.
        assertTrue(!ok || ret);
    }
}

// Adversarial counterpart: a callee that accepts the forwarded call and returns true (or simply succeeds)
contract AcceptingCallee {
    // accept any calldata and return success
    fallback() external payable {
        // do nothing, just succeed
    }
}

