pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: from (actor initiating on behalf of), v (value), decimals, and the single-to address
    function testFuzz_property(address from, uint8 v, uint8 decimals, address to) public {
        // admissible domain: require non-zero to (avoid zero-address edge-case) and ensure _tos length > 0 by using one-element array
        vm.assume(to != address(0));
        // keep v and decimals wide; no tight bounding so fuzzer can find mismatches

        address[] memory tos = new address[](1);
        tos[0] = to;

        // Deploy a helper callee that always accepts the transferFrom call (returns true) to ensure the internal calls succeed.
        // This models a normal token/contract which the reference expects to succeed.
        AcceptingCallee acceptor = new AcceptingCallee();

        // Call transfer and capture its returned boolean by try/catch to observe non-reverting completion and return value.
        bool ok;
        try c.transfer(from, address(acceptor), tos, v, decimals) returns (bool ret) {
            // if call did not revert, we expect the reference to return true for all admissible inputs
            ok = ret;
        } catch {
            // if it reverted, mark as failure of completion
            ok = false;
        }

        // The universal property: for all admissible inputs (non-empty tos and an accepting callee), reference returns true.
        // The mutant that returns false will therefore fail this assertion for some inputs — the fuzzer can find them.
        assertTrue(ok);
    }
}

// Minimal adversarial (here cooperative) helper that accepts the low-level call and returns true.
contract AcceptingCallee {
    // match selector transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) public pure returns (bool) {
        return true;
    }
}

